using AfriWallet.Merchants.Intelligence.Application.Abstractions;using AfriWallet.Merchants.Intelligence.Application.Models;namespace AfriWallet.Merchants.Intelligence.Infrastructure;public sealed class SandboxMerchantIntelligenceSource:IMerchantIntelligenceSource{private readonly Dictionary<string,MerchantIntelligenceSnapshot> _items=new(StringComparer.OrdinalIgnoreCase);public void Set(MerchantIntelligenceSnapshot snapshot)=>_items[snapshot.MerchantId]=snapshot;public Task<MerchantIntelligenceSnapshot?> GetAsync(string merchantId,CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();_items.TryGetValue(merchantId,out var result);return Task.FromResult(result);}}
